\label{theorem_uplink_rate}
Using the use-and-then-forget (UatF) bounding technique and the inverse Wishart property $1/\mathbb{E}[\|\boldsymbol{u}_k\|^2] = (N_{\mathtt{r}} - K)\xi_k$, the achievable closed-form offloading rate for the priority MEC user $k$ is given by
\begin{equation}\label{eq:up_link_rate}
    R_k^\mathtt{cp}(\boldsymbol{p}, \rho) = B \log_2 \left( 1 + \frac{p_k (N_{\mathtt{r}} - K) \xi_k}{I^{\mathtt{er}}(\boldsymbol{p}) + I^\mathtt{se}(\rho) + \sigma_c^2} \right)
\end{equation}
where $\boldsymbol{p} \triangleq \{p_k, p_{k'}\}_{\forall k, k' \in \mathcal{K}}$, $I^{\mathtt{er}}(\boldsymbol{p}) \triangleq \sum_{j \in \mathcal{K}_{\mathtt{MEC}} } p_j \epsilon_j + \sum_{k' \in \mathcal{K}_{\mathtt{com}} } p_{k'} \epsilon_{k'}$ represents the inter-user interference, and the co-site radar cross-interference factor $I^\mathtt{se}(\rho)$ is given as
\begin{equation}\label{eq:I_k_sen_final}
    I^\mathtt{se}(\rho) \triangleq \rho \left( |\alpha|^2 N_{\mathtt{t}} + \frac{\chi_{\mathtt{SI}} \kappa_{\mathtt{SI}} \mathcal{D}_{\mathtt{H}}(\theta, \phi) \mathcal{D}_{\mathtt{V}}(\phi)}{N_{\mathtt{t}} (\kappa_{\mathtt{SI}}+1)} + \frac{\chi_{\mathtt{SI}}}{\kappa_{\mathtt{SI}}+1} \right).
\end{equation}
Here, $\mathcal{D}_{\mathtt{H}}(\theta, \phi)$ and $\mathcal{D}_{\mathtt{V}}(\phi)$ denote the expanded spatial Dirichlet beamforming kernels for the horizontal and vertical transmit sub-arrays, respectively, defined as:
\begin{align}
    \mathcal{D}_{\mathtt{H}}(\theta, \phi) &\triangleq \left[ \frac{\sin\left(\frac{N_{\mathtt{t},\mathtt{h}} \pi}{2} (\sin\theta \sin\phi - \sin\theta_{\mathtt{SI}} \sin\phi_{\mathtt{SI}})\right)}{\sin\left(\frac{\pi}{2} (\sin\theta \sin\phi - \sin\theta_{\mathtt{SI}} \sin\phi_{\mathtt{SI}})\right)} \right]^2 \\
    \mathcal{D}_{\mathtt{V}}(\phi) &\triangleq \left[ \frac{\sin\left(\frac{N_{\mathtt{t},\mathtt{v}} \pi}{2} (\cos\phi - \cos\phi_{\mathtt{SI}})\right)}{\sin\left(\frac{\pi}{2} (\cos\phi - \cos\phi_{\mathtt{SI}})\right)} \right]^2
\end{align}
where $\theta_{\mathtt{SI}}$ and $\phi_{\mathtt{SI}}$ are the internal physical leakage angles from the transmit to the receive array panel at the full-duplex access point.

Symmetrically, the closed-form achievable uplink communication rate for user $k' \in \mathcal{K}_{\mathtt{com}}$ is given as
\begin{equation}\label{eq:comm_rate}
    R_{k'}^\mathtt{cm}(\boldsymbol{p}, \rho) = B \log_2 \left( 1 + \frac{p_{k'} (N_{\mathtt{r}} - K) \xi_{k'}}{I^{\mathtt{er}}(\boldsymbol{p}) + I^\mathtt{se}(\rho) + \sigma_c^2} \right).
\end{equation}

\label{remark_dof_limits}
For fixed $K$, $N_{\mathtt{t}}$, pilot powers, and radar power, the rate in \eqref{eq:up_link_rate} grows as $B\log_2 N_{\mathtt{r}}+\mathcal{O}(1)$ when user powers are fixed. If all user powers instead scale as $p_u=P_u^{\mathtt{ref}}/N_{\mathtt{r}}$, $u\in\mathcal K$, then \cite{Ngo2013}
\begin{equation}\label{eq:ultimate_upper_bound}
\bar R_k^{\mathtt{cp},\infty}(\rho)=B\log_2\left(1+\frac{P_k^{\mathtt{ref}}\xi_k}{I^{\mathtt{se}}(\rho)+\sigma_c^2}\right).
\end{equation}
Thus, radar interference remains in the limiting rate under this power-scaling regime.

\label{LM_lemma1}
Due to the intractability of colored RSI in FD-mMIMO ISCC systems, we upper-bound it as an equivalent spatially white Gaussian process \cite{Salem_2025}. Over a large coherence processing interval ($L \gg 1$), the aggregate interference-plus-noise covariance matrix simplifies to a scaled identity:
\begin{equation}\label{eq:lemma1}
    \boldsymbol{R}_{\mathtt{in}} \triangleq \mathbb{E}\{\boldsymbol{n}_{\mathtt{eq}}\boldsymbol{n}_{\mathtt{eq}}^{\mathtt{H}}\} = \left( I^{\mathtt{up}}(\boldsymbol{p}) + \sigma_{\mathtt{rad}}^2(\rho) \right) \boldsymbol{I}_{N_{\mathtt{r}} L}
\end{equation}
where $I^{\mathtt{up}}(\boldsymbol{p}) \triangleq \sum_{k \in \mathcal{K}_{\mathtt{MEC}}} p_k \beta_k + \sum_{k' \in \mathcal{K}_{\mathtt{com}}} p_{k'} \beta_{k'}$ and $\sigma_{\mathtt{rad}}^2(\rho) \triangleq \chi_{\mathtt{SI}} \rho + \sigma_c^2$ denote the aggregate uplink interference and the effective radar noise variance, respectively.

\label{theorem_CRLB}
   The CRLBs for $\theta$ and $\phi$ in the FD-mMIMO ISCC system admit the following closed-form expressions:
    \begin{align}
        \text{CRLB}_\theta(\boldsymbol{p}, \rho) &= \frac{I^{\mathtt{up}}(\boldsymbol{p}) + \sigma_{\mathtt{rad}}^2(\rho)}{2L \rho} \mathcal{G}_\theta(\tilde{\boldsymbol{w}}) \label{eq:CRLB_theta} \\
        \text{CRLB}_\phi(\boldsymbol{p}, \rho) &= \frac{I^{\mathtt{up}}(\boldsymbol{p}) + \sigma_{\mathtt{rad}}^2(\rho)}{2L \rho} \mathcal{G}_\phi(\tilde{\boldsymbol{w}}) \label{eq:CRLB_phi}
    \end{align}
    where $\mathcal{G}_\theta(\tilde{\boldsymbol{w}})$ and $\mathcal{G}_\phi(\tilde{\boldsymbol{w}})$ are power-independent geometric multipliers defined by
    \begin{align} 
        \mathcal{G}_\theta(\tilde{\boldsymbol{w}}) &\triangleq \left( \tilde{c}_{\theta\theta}(\tilde{\boldsymbol{w}}) - \frac{|\tilde{c}_{\theta\phi}(\tilde{\boldsymbol{w}})|^2}{\tilde{c}_{\phi\phi}(\tilde{\boldsymbol{w}}) - \frac{\|\tilde{\boldsymbol{c}}_{\phi\bar{\boldsymbol{\alpha}}}(\tilde{\boldsymbol{w}})\|^2}{\tilde{c}_{\bar{\boldsymbol{\alpha}}\bar{\boldsymbol{\alpha}}}(\tilde{\boldsymbol{w}})}} \right)^{-1} \label{eq:steering_vector_theta} \\
        \mathcal{G}_\phi(\tilde{\boldsymbol{w}}) &\triangleq \left( \tilde{c}_{\phi\phi}(\tilde{\boldsymbol{w}}) - \frac{|\tilde{c}_{\theta\phi}(\tilde{\boldsymbol{w}})|^2}{\tilde{c}_{\theta\theta}(\tilde{\boldsymbol{w}}) - \frac{\|\tilde{\boldsymbol{c}}_{\theta\bar{\boldsymbol{\alpha}}}(\tilde{\boldsymbol{w}})\|^2}{\tilde{c}_{\bar{\boldsymbol{\alpha}}\bar{\boldsymbol{\alpha}}}(\tilde{\boldsymbol{w}})}} \right)^{-1}. \label{eq:steering_vector_phi}
    \end{align}

\label{remark_tractability_CRLB}
For the case of perfect beam alignment, \textit{i.e.} $(\tilde{\theta}, \tilde{\phi}) = (\theta, \phi)$, the normalized transmit beamformer evaluates to $\tilde{\boldsymbol{w}} = \frac{1}{\sqrt{N_{\mathtt{t}}}}\boldsymbol{a}_{\mathtt{t}}$. Applying the spatial orthogonality properties of centered planar arrays ($\boldsymbol{a}_{\mathtt{t}}^{\mathtt{H}} \dot{\boldsymbol{a}}_{\mathtt{t},\theta} = 0$ and $\boldsymbol{a}_{\mathtt{t}}^{\mathtt{H}} \dot{\boldsymbol{a}}_{\mathtt{t},\phi} = 0$), the geometric trace constants $\tilde{c}_{(\cdot)}(\tilde{\boldsymbol{w}})$ explicitly simplify to:
\begin{align}
    &\tilde{c}_{\theta\theta} = |\alpha|^2 N_{\mathtt{t}} U_{\mathtt{r},\theta}, \quad \tilde{c}_{\phi\phi} = |\alpha|^2 N_{\mathtt{t}} U_{\mathtt{r},\phi},\label{eq:c_theta_theta_final} \\
    &\Re\{\tilde{c}_{\theta\phi}\} = |\alpha|^2 N_{\mathtt{t}} U_{\mathtt{r},\theta\phi},\label{eq:c_theta_phi_final} \\
    &\boldsymbol{\tilde{c}}_{\bar{\boldsymbol{\alpha}}\bar{\boldsymbol{\alpha}}} = N_{\mathtt{t}} N_{\mathtt{r}} \boldsymbol{I}_2, \quad \tilde{\boldsymbol{c}}_{\theta\bar{\boldsymbol{\alpha}}} = \boldsymbol{0}, \quad \tilde{\boldsymbol{c}}_{\phi\bar{\boldsymbol{\alpha}}} = \boldsymbol{0}.\label{eq:c_alpha_alpha_final}
\end{align}
Since $\tilde{\boldsymbol{c}}_{\theta\bar{\boldsymbol{\alpha}}} = \tilde{\boldsymbol{c}}_{\phi\bar{\boldsymbol{\alpha}}} = \boldsymbol{0}$, angular estimation decouples from $\bar{\boldsymbol{\alpha}}$, yielding the simplified CRLBs in \eqref{eq:CRLB_final_theta}--\eqref{eq:CRLB_final_phi}. For the $N_{\mathtt{rh}} \times N_{\mathtt{rv}}$ Y-Z planar receive array, the spatial energy terms are:
\begin{align}
    &U_{\mathtt{r},\theta} = \frac{N_{\mathtt{r}}}{12} \pi^2 \cos^2(\theta) \sin^2(\phi) (N_{\mathtt{rh}}^2-1), \\
    &U_{\mathtt{r},\phi} = \frac{N_{\mathtt{r}}}{12} \pi^2 \Big( (N_{\mathtt{rh}}^2-1) \sin^2(\theta) \cos^2(\phi) \nonumber\\ 
    &+ (N_{\mathtt{rv}}^2-1) \sin^2(\phi) \Big), \\
    &U_{\mathtt{r},\theta\phi} = \frac{N_{\mathtt{r}}}{12} \pi^2 \sin(\phi) \cos(\phi) \sin(\theta) \cos(\theta) (N_{\mathtt{rh}}^2-1).
\end{align}
In \eqref{eq:CRLB_final_theta}--\eqref{eq:CRLB_final_phi}, $N_{\mathtt{t}}$ scales the gain while $N_{\mathtt{r}}$ governs the angular terms. Furthermore, the CRLBs' proportionality to $I^{\mathtt{up}}(\boldsymbol{p})$ and inverse proportionality to $\rho$ dictate a fundamental trade-off, making joint power allocation essential to preserve sensing performance.

\label{remark_Nt_CRLB}
    For fixed powers and target angles away from singular geometries, the angular CRLBs scale as $\mathcal{O}(1/N_{\mathtt{t}})$ with fixed $N_{\mathtt{r}}$. For a square receive UPA and fixed $N_{\mathtt{t}}$, they scale as $\mathcal{O}(1/N_{\mathtt{r}}^2)$.
\begin{proof}
    See Appendix~\ref{Proof_remark_Nt_CRLB}.
\end{proof}
